<?php
/**
 * @package PlugixaExam
 */

declare( strict_types = 1 );

namespace PlugixaExam\Core\App;

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

/**
 * Translated strings for the React admin.
 *
 * NOT `wp_set_script_translations()`. That mechanism needs a `.json` translation file per
 * script handle, generated by WP-CLI from the built JS — which means the translations are
 * keyed to a bundle filename that changes with every content hash, and a rebuild silently
 * un-translates the admin. A flat key-to-string map passed through the page has no such
 * coupling, and it costs one small object in the HTML.
 *
 * THE FREE BUILD SHIPS NO PREMIUM STRINGS. Each module appends its own through
 * `plugixa_exam_admin_i18n_strings`, so a premium module that is not installed contributes
 * nothing — which matters beyond tidiness: WordPress.org treats premium-only labels in a
 * free build as evidence of locked functionality.
 */
final class Strings {

	/**
	 * @return array<string, string>
	 */
	public static function all(): array {
		$strings = array(
			// Shell.
			'appName'        => __( 'Plugixa Exam', 'plugixa-exam' ),
			'dashboard'      => __( 'Dashboard', 'plugixa-exam' ),
			'dashboardDesc' => __( 'The landing screen: what needs doing, and how the exams are going.', 'plugixa-exam' ),
			'settings'       => __( 'Settings', 'plugixa-exam' ),
			'settingsDesc' => __( 'Number formatting, colours, pages, and the options other apps add.', 'plugixa-exam' ),
			'apps'           => __( 'Apps', 'plugixa-exam' ),
			'loading'        => __( 'Loading…', 'plugixa-exam' ),
			'search'         => __( 'Search', 'plugixa-exam' ),
			'searchPlaceholder'  => __( 'Search…', 'plugixa-exam' ),

			// The header and sidebar (shell/Layout, CommandPalette, UserMenu).
			/* translators: The product name beside the Plugixa logo in the sidebar, shown in small capitals. */
			'brandBadge'         => __( 'Exam', 'plugixa-exam' ),
			'menu'               => __( 'Menu', 'plugixa-exam' ),
			'viewSite'           => __( 'View site', 'plugixa-exam' ),
			'envLocal'           => __( 'Local', 'plugixa-exam' ),
			'envDevelopment'     => __( 'Development', 'plugixa-exam' ),
			'envStaging'         => __( 'Staging', 'plugixa-exam' ),
			'envNotLive'         => __( 'This is not the live site', 'plugixa-exam' ),
			'account'            => __( 'Account', 'plugixa-exam' ),
			'navProfile'         => __( 'Profile', 'plugixa-exam' ),
			'navExitAdmin'       => __( 'Exit to WordPress', 'plugixa-exam' ),
			'navLogout'          => __( 'Log out', 'plugixa-exam' ),
			'searchTrigger'      => __( 'Search exams, questions, people, pages…', 'plugixa-exam' ),
			'searchTriggerPages' => __( 'Search pages…', 'plugixa-exam' ),
			/* translators: A heading in the search palette, above the list of screens it can open. */
			'paletteGoTo'        => __( 'Go to', 'plugixa-exam' ),
			/* translators: {query} is what the person typed into the search palette. Keep the braces. */
			'paletteEmpty'       => __( 'Nothing matches “{query}”.', 'plugixa-exam' ),
			/* translators: Follows the arrow-key symbols in the search palette's footer: "↑ ↓ to move". */
			'paletteMove'        => __( 'to move', 'plugixa-exam' ),
			/* translators: Follows the Enter key symbol in the search palette's footer: "Enter to open". */
			'paletteOpen'        => __( 'to open', 'plugixa-exam' ),
			'paletteHint'        => __( 'Type two letters to search', 'plugixa-exam' ),

			// Actions.
			'save'           => __( 'Save', 'plugixa-exam' ),
			'saving'         => __( 'Saving…', 'plugixa-exam' ),
			'saved'          => __( 'Saved', 'plugixa-exam' ),
			'cancel'         => __( 'Cancel', 'plugixa-exam' ),
			'delete'         => __( 'Delete', 'plugixa-exam' ),
			'edit'           => __( 'Edit', 'plugixa-exam' ),
			'create'         => __( 'Create', 'plugixa-exam' ),
			'duplicate'      => __( 'Duplicate', 'plugixa-exam' ),
			'restore'        => __( 'Restore', 'plugixa-exam' ),
			'retry'          => __( 'Try again', 'plugixa-exam' ),
			'done'           => __( 'Done', 'plugixa-exam' ),
			'copy'           => __( 'Copy', 'plugixa-exam' ),
			'copied'         => __( 'Copied', 'plugixa-exam' ),

			// Asked for by `shared/components/ColourField.tsx` and by every form with a
			// save bar, so they are core rather than the property of whichever screen
			// happened to need them first.
			'resetToDefault' => __( 'Reset to default', 'plugixa-exam' ),
			'unsavedChanges' => __( 'Unsaved changes', 'plugixa-exam' ),
			'allSaved'       => __( 'Everything is saved.', 'plugixa-exam' ),

			// Words that turn up as a column heading or a field label in several modules,
			// and are here rather than in whichever one happened to need them first.
			'status'         => __( 'Status', 'plugixa-exam' ),
			'minutes'        => __( 'Minutes', 'plugixa-exam' ),

			// States.
			'empty'          => __( 'Nothing here yet.', 'plugixa-exam' ),
			'noResults'      => __( 'No results match your search.', 'plugixa-exam' ),
			'errorTitle'     => __( 'Something went wrong', 'plugixa-exam' ),
			'errorBody'      => __( 'The page could not be displayed. Try again, and if it keeps happening tell your site administrator what you were doing.', 'plugixa-exam' ),
			'forbidden'      => __( 'You do not have access to this area.', 'plugixa-exam' ),
			'offline'        => __( "Couldn't reach the site — will retry", 'plugixa-exam' ),

			// Trash.
			'trash'          => __( 'Trash', 'plugixa-exam' ),
			'formatParagraph' => __( 'Paragraph', 'plugixa-exam' ),
			'formatHeading2' => __( 'Heading 2', 'plugixa-exam' ),
			'formatHeading3' => __( 'Heading 3', 'plugixa-exam' ),
			'confirmDelete'  => __( 'Delete this item?', 'plugixa-exam' ),
			'key' => __( 'Fallback', 'plugixa-exam' ),
		);

		/**
		 * Add a module's admin strings.
		 *
		 * @param array<string, string> $strings Accumulated strings.
		 */
		return (array) apply_filters( 'plugixa_exam_admin_i18n_strings', $strings );
	}
}
